{"s6_c04_status_report_joke_007","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"How many operators does it take to change a light bulb?",2,"Don't",1,"None - power's out",2,"Not a joke, just a status report"}},
{"s6_c04_wedge_the_can_008","any",2,"reg=elite|tmp=veteran|day=5,999|mood=sad",{1,"Somebody toss that can of dip off the dash, it rolls every turn",2,"It's Hollis's",1,"Wedge it, then, so it doesn't roll"}},
{"s6_c04_abroad_clause_009","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=funny",{1,"Policy covers death abroad",2,"Kentucky's not abroad",1,"Read that clause three times last night - Kentucky is abroad now"}},
{"s6_c04_texas_training_010","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=sad|world=hot",{1,"Last thing I told Denise was two weeks, training, Texas",2,"Close",1,"It's hot, that's the only part I got right"}},
{"s6_c04_tate_sing_011","any",2,"reg=elite|tmp=veteran|day=6,999|mood=sad",{1,"Thirty-six today",2,"Tate would've sung",1,"Tate couldn't sing",2,"He'd have done it anyway, standing on something"}},
