{"s6_c04_this_horse_014","any",2,"reg=elite|tmp=veteran|hour=12,22|mood=funny",{1,"Check",2,"That's not how the horse moves",1,"It's how this horse moves",2,"You've cheated for nine days",1,"And you've kept playing for nine days"}},
{"s6_c04_clipboard_015","any",2,"reg=elite|role=elite_delta|tmp=veteran|mood=funny",{1,"Selection was worse than this",2,"Selection didn't try to eat you",1,"Selection had a cadre man with a clipboard who wrote nothing down - give me teeth any day"}},
{"s6_c04_eleven_boots_016","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"If I get bit, you take the boots",2,"You're a ten and a half, I'm an eleven",1,"Then suffer, they're good boots"}},
{"s6_c04_four_games_out_017","any",2,"reg=elite|tmp=veteran|day=4,999|mood=funny",{1,"Reds were four games out when we came in",2,"Further out now",1,"Everybody's further out now"}},
{"s6_c04_one_round_expended_018","any",2,"reg=elite|tmp=veteran|mood=grim|world=building",{1,"Doll in a kitchen said 'I love you' when I stepped on it",2,"Batteries",1,"I know it's batteries, I put a round in it anyway",2,"Log it",1,"Log what?",2,"One round expended"}},
{"s6_c04_only_on_aircraft_019","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"You pray?",2,"Only on the aircraft",1,"There's no aircraft",2,"That's what I pray about"}},
{"s6_c04_last_morphine_020","any",2,"reg=elite|tmp=veteran|day=5,999|mood=sad",{1,"You used the last morphine on the farmer",2,"I did",1,"He was bit, he had an hour",2,"He was scared for that hour, that's what it's for"}},
{"s6_c04_both_numbers_021","any",2,"reg=elite|tmp=veteran|day=8,999|mood=grim",{1,"Six came in",2,"Four",1,"Six came in - four now, I say both numbers - every time"}},
{"s6_c04_revival_all_welcome_022","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Church sign in Rosewood says revival all week, all welcome",2,"Turnout?",1,"Standing room only, nobody in there is sitting"}},
{"s6_c04_angola_dry_023","any",2,"reg=elite|role=mercenary|tmp=veteran|hour=11,18|mood=calm",{1,"Angola was hotter - but dry",2,"Everybody has a place where the heat was dry",1,"Angola's was, you could hang a shirt and it was dry before you let go"}},
{"s6_c04_grids_right_024","any",2,"reg=elite|tmp=veteran|hour=4,8|mood=warm",{1,"You talked in your sleep",2,"What'd I say?",1,"Grid coordinates - then 'Mom'",2,"Were the grids right?",1,"The grids were right"}},
{"s6_c04_hand_not_cold_025","any",2,"reg=elite|tmp=veteran|day=5,999|mood=grim",{1,"Your hand",2,"Cold",1,"It's ninety degrees",2,"Then it's not cold - leave it"}},
{"s6_c04_easy_job_026","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=sad",{1,"My brother's with the 101st at Campbell",2,"Campbell's outside the line",1,"He always said I got the easy job, I'd like to hear him say it one more time"}},
{"s6_c04_ball_cap_bet_027","any",3,"reg=elite|tmp=veteran|mood=funny",{1,"Five dollars says the next one's wearing a ball cap",2,"Everybody in Kentucky wears a ball cap",3,"Ten says it's a Wildcats cap",1,"Nobody's taking that bet - get a better bet"}},
{"s6_c04_quiet_the_dog_028","any",2,"reg=elite|tmp=veteran|day=4,999|mood=warm",{1,"Dog needs a name",2,"Dog needs to be quiet",1,"Quiet, then",2,"That's not a name",1,"He comes when I say it"}},
{"s6_c04_snakes_driveway_029","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=sad|world=building",{1,"Fourth of July I was grilling bratwurst in Fayetteville",2,"Kids?",1,"Lighting those black snake things on the driveway, the marks are still on the concrete, I bet"}},
{"s6_c04_liar_liar_030","any",2,"reg=elite|tmp=veteran|hour=22,4|mood=warm",{1,"You scared?",2,"No",1,"Me neither",2,"Liar",1,"Liar"}},
{"s6_c04_merc_pretoria_031","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=calm",{1,"Why take a job in Kentucky?",2,"Paid in dollars - no malaria, nobody said anything about the rest"}},
{"s6_c04_hot_shower_ranking_032","any",3,"reg=elite|tmp=veteran|day=7,999|mood=funny",{1,"First thing when we get out",2,"Shower - hot - an hour",3,"Steak - rare - two",1,"I'm going to sit in a room with the air conditioning on and not guard anything"}},
{"s6_c04_medic_hold_still_033","any",2,"reg=elite|tmp=veteran|mood=calm|world=door",{1,"Hold still",2,"It's a splinter",1,"It's a splinter from a door they were chewing on - hold still"}},
{"s6_c04_wedding_ring_034","any",2,"reg=elite|tmp=veteran|day=10,999|mood=sad",{1,"You're wearing your ring",2,"Took it off for the op - put it back on Friday",1,"Why?",2,"So whoever finds me knows to tell somebody"}},
{"s6_c04_weight_room_035","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"You're doing push-ups",2,"Fifty a day",1,"We walked twenty miles today",2,"Walking's legs, this is for when I get home and she asks"}},
