{"s6_c04_card_game_losses_040","any",3,"reg=elite|tmp=veteran|hour=12,21|mood=funny",{1,"You owe me nine hundred dollars in rummy",2,"Put it on my tab",3,"His tab is at eleven thousand",2,"I'm good for it - after"}},
{"s6_c04_crack_music_box_041","any",2,"reg=elite|tmp=veteran|day=8,999|mood=sad",{1,"You took a music box out of that house",2,"Weighs nothing",1,"Everything weighs something",2,"Then I'll carry it, you won't feel a thing"}},
{"s6_c04_bite_joke_dies_042","any",3,"reg=elite|tmp=veteran|mood=grim",{1,"Which one of us turns first, you think?",2,"Vance, he never finishes anything",3,"Vance finished",2,"Yeah, sorry - forgot"}},
{"s6_c04_poker_face_043","any",2,"reg=elite|role=mercenary|tmp=veteran|day=12,999|mood=calm",{1,"Four months left on my contract",2,"Planning to finish it?",1,"Planning to be somewhere on the day it ends - anywhere, that's the plan"}},
