{"s6_c05_client_needs_rescue_022","any",1,"reg=elite|role=mercenary|tmp=veteran|mood=funny",{1,"Twelve years of contracts - Angola - Croatia, a mine in Colombia",1,"First job where the client's the one who needs rescuing",1,"From his own boxes"}},
