{"s6_c05_cut_name_tape_034","any",2,"reg=elite|tmp=veteran|day=20,999|mood=grim",{1,"Cut your name tape off",2,"Why?",1,"Raider on nineteen is reading out soldiers' names off shirts - asking who's missing one"}},
{"s6_c05_hi_dwayne_035","any",3,"reg=elite|tmp=veteran|day=18,999|mood=funny",{1,"Uniform's gone, found a work shirt at the hardware store",2,"Name on the pocket says Dwayne",3,"Morning, Dwayne",1,"Dwayne's got more mags than any of you"}},
{"s6_c05_working_for_letterhead_036","any",2,"reg=elite|role=mercenary|tmp=veteran|day=12,999|mood=grim",{1,"Orders are still on the client's letterhead",2,"Client's office in Louisville is a burned-out shell",1,"Then we're working for letterhead"}},
{"s6_c05_dont_talk_first_037","any",2,"reg=elite|tmp=veteran|hour=20,2|mood=grim",{1,"If it's me",2,"It won't be",1,"If it's me, don't talk first, the talking is for you, not for me",2,"Understood"}},
{"s6_c05_no_town_lights_038","any",2,"reg=elite|tmp=veteran|day=5,999|hour=22,4|mood=calm",{1,"More stars than the desert",2,"No town lights",1,"No town"}},
{"s6_c05_ask_me_tomorrow_039","any",2,"reg=elite|tmp=veteran|hour=19,1|mood=sad",{1,"You alright?",2,"Ask me tomorrow",1,"I'll ask you tomorrow"}},
{"s6_c05_kid_walkie_040","any",2,"reg=elite|tmp=veteran|day=3,999|mood=sad|world=door",{1,"Found a kid's walkie-talkie in the yard, somebody's on the other one",2,"Talking?",1,"Asking if Daddy's there, every few minutes",2,"Pull the batteries",1,"I know, I've had my thumb on the battery door for ten minutes"}},
{"s6_c05_write_down_sheriff_041","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Sheriff in {town} shook my hand, didn't ask one question",2,"Smart man",1,"Said he didn't want to know anything he'd have to write down later"}},
{"s6_c05_no_date_note_042","any",2,"reg=elite|tmp=veteran|day=10,999|mood=sad|world=water",{1,"Found Hotel Four's truck",2,"And?",1,"Keys in it - radio gone, note on the dash says 'gone to the river'",2,"When?",1,"No date - Hotel Four never dated anything"}},
{"s6_c05_pt_test_043","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|day=6,999|mood=funny",{1,"PT test was due next month",2,"Run the two-mile through Muldraugh, best time you'll ever post"}},
{"s6_c05_hands_after_contact_044","any",2,"reg=elite|tmp=veteran|day=4,999|mood=fear",{1,"Hands won't quit",2,"Adrenaline",1,"Contact was an hour ago",2,"Then it's the other thing - sit - it passes, it passed for me Thursday"}},
{"s6_c05_screen_porch_sleep_045","any",3,"reg=elite|tmp=veteran|hour=21,2|mood=warm",{1,"You're up - go down",2,"It's not my shift",3,"He took your shift - don't argue with him about it",2,"Why?",1,"Because you took mine on Sunday and never said - go down"}},
{"s6_c05_squad_math_046","any",3,"reg=elite|tmp=veteran|day=15,999|mood=grim|world=building",{1,"Three of us can't clear a house",2,"Three of us cleared one yesterday",3,"Barely",1,"Barely is the new standard - write it on the wall"}},
{"s6_c05_merc_contempt_boots_047","any",2,"reg=elite|role=mercenary|tmp=veteran|mood=angry",{1,"Raider wearing Guard boots, laces untied",2,"Took them off a body",1,"Took them off a better man and couldn't be bothered to tie them"}},
{"s6_c05_crack_old_song_048","any",2,"reg=elite|tmp=veteran|hour=20,1|mood=sad|world=vehicle",{1,"You're whistling the tune from the ice cream truck on post",2,"Am I?",1,"All afternoon, my kids chase that truck every Thursday",2,"I'll stop",1,"Didn't ask you to"}},
{"s6_c05_thousand_meters_049","any",2,"reg=elite|role=elite_delta|tmp=veteran|mood=calm",{1,"Group on the ridge, nine hundred meters, moving like people",2,"Armed?",1,"One rifle, the rest are carrying a mattress - let them go"}},
{"s6_c05_last_one_standing_joke_050","any",3,"reg=elite|tmp=veteran|day=20,999|mood=funny|world=vehicle",{1,"Whoever's last gets the book deal",2,"Nobody's reading books",3,"Then the last one gets the truck",1,"The truck's a better deal anyway"}},
{"s6_gear_motor_oil_001","any",2,"reg=elite|tmp=veteran|day=4,999|mood=funny",{1,"Who's got the CLP?",2,"Used the last of it on the SAW",1,"So we're oiling rifles with what?",2,"Quart of ten-weight off a gas station shelf on 31W",1,"Outstanding"}},
{"s6_gear_mag_count_002","any",1,"reg=elite|tmp=veteran|hour=21,4|mood=calm",{1,"Twenty-eight - twenty-nine - thirty",1,"Four mags, one-twenty, one in the chamber",1,"Enough for a bad afternoon, not enough for a bad week"}},
{"s6_gear_soft_springs_003","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Springs are going soft - Download every mag to twenty-eight",2,"Doc says that's a myth",1,"Doc also said we'd be out of this county in seventy-two hours",2,"Twenty-eight it is"}},
{"s6_gear_last_double_a_004","any",3,"reg=elite|tmp=veteran|day=6,999|hour=20,5|mood=grim",{1,"Last two double-A's for the goggles",2,"Put them in mine, I've got the midnight watch",3,"You've got every watch",2,"Then it works out"}},
{"s6_gear_carboned_can_005","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Can on the MP5 is so packed with carbon it rattles",2,"Still beats the shotgun, the shotgun rings a dinner bell for half of West Point"}},
{"s6_gear_round_log_006","any",2,"reg=elite|tmp=veteran|mood=grim",{1,"Round count?",2,"Nine expended, seven down",1,"Two misses",2,"One miss, one went through two of them",1,"Logged as a miss"}},
{"s6_gear_knife_hour_007","any",2,"reg=elite|tmp=veteran|mood=funny|world=vehicle",{1,"You've been on that knife for an hour",2,"It's not sharp yet",1,"It'd take the paint off the truck",2,"The truck isn't trying to eat me"}},
{"s6_gear_morning_check_008","any",1,"reg=elite|tmp=veteran|hour=4,8|mood=calm",{1,"Chamber check - safe - mag seated",1,"Light works, knife on the left",1,"Same as yesterday - good"}},
{"s6_gear_humidity_panama_009","any",3,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=funny",{1,"Humidity in this county is eating the finish off everything I own",2,"Kentucky in July, worse than jungle school in Panama",3,"Panama had better beer",1,"Panama had beer at all"}},
{"s6_gear_no_shots_under_roof_010","any",2,"reg=elite|tmp=veteran|mood=grim|world=building",{1,"Knife work only inside houses, no shots under a roof",2,"Copy - and when there's six of them in a hallway?",1,"Then you back out of the hallway"}},
{"s6_gear_soft_points_011","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Gun counter in {town} had four boxes of five-five-six",2,"Commercial?",1,"Commercial soft points - it'll feed",2,"Keep it separate, I don't want it mixed in with the green tip"}},
{"s6_gear_dentist_box_012","any",2,"reg=elite|tmp=veteran|mood=funny",{1,"Found nine mil for the pistols",2,"How much?",1,"One box of hollow points, out of a dentist's nightstand",2,"Tell the dentist thanks",1,"I did, he didn't answer"}},
{"s6_gear_dropped_mag_013","any",3,"reg=elite|tmp=veteran|mood=angry",{1,"Who left a magazine at the rally point?",2,"Not me",3,"Not me",1,"Then it climbed out of a pouch on its own - everybody count - now"}},
{"s6_gear_peeling_sole_014","any",2,"reg=elite|tmp=veteran|day=10,999|mood=calm",{1,"Left boot's done - Sole's peeling",2,"Hundred-mile-an-hour tape",1,"Taped it three days ago, the tape's done too",2,"Shoe store in {town} - pick your size and don't sit down in the aisle to try them on"}},
{"s6_gear_show_me_feet_015","any",2,"reg=elite|role=elite_operator,elite_delta|tmp=veteran|mood=calm",{1,"Feet",2,"Dry",1,"Show me",2,"They're dry, Sergeant",1,"Then showing me costs you nothing"}},
{"s6_gear_front_sight_016","any",1,"reg=elite|tmp=veteran|hour=22,3|mood=grim",{1,"Front sight post - put it on the forehead - press",1,"Front sight post",1,"Nobody out here tonight but me and the front sight post"}},
{"s6_gear_pull_tracers_017","any",2,"reg=elite|tmp=veteran|mood=calm",{1,"Strip the tracers out of the SAW belts",2,"Makes it harder to walk the rounds in",1,"Makes it harder for everybody on Dixie Highway to see where we're sitting",2,"Stripping them"}},
{"s6_gear_quiet_doors_018","any",3,"reg=elite|tmp=veteran|mood=funny|world=door",{1,"Shotgun's better for houses",2,"Shotgun's better for waking everything from here to Ekron",3,"Everything's loud, a screen door is loud",2,"Then open screen doors quieter"}},
